private int parseEndOfLine(String headerPart, int end) throws Exception {
    int i = end;
    while (i >= 0 && (headerPart.charAt(i) != '\r' || headerPart.charAt(i+1) != '\n')) {
        i--;
    }
    // If we reached the beginning of the header part without finding a \r\n, it means the header part ends with \r\n
    if (i < 0) {
        return 0;
    }
    return i + 2; // Return the index of the next character after \r\n to indicate end of line
}

