public static List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();

        // Ensure start time and end time are small enough to fetch data
        long fetchDataDuration = 100000; // Example duration in milliseconds
        while (end - start >= fetchDataDuration) {
            long rangeStart = start;
            long rangeEnd = start + fetchDataDuration;
            timeRanges.add(new TimeRange(rangeStart, rangeEnd));
            start = rangeEnd;
        }

        // Include the last remaining range if it exceeds the fetch duration
        timeRanges.add(new TimeRange(start, end));

        return timeRanges;
    }

