public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size++;
        } else if (ch <= 0xFF) {
            size += 2;
        } else if (ch <= 0x7FFF) {
            size += 3;
        } else if (ch <= 0xFFFF) {
            size += 4;
        } else if (ch <= 0x10FFFF) {
            size += 5;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character: " + ch);
        }
    }
    return size;
}

