public int readTag() throws IOException {
    int tagNumber = 0;

    while ((tagNumber & 7) == 0 && reader.hasNext()) {
        byte nextByte = reader.read();

        if ((nextByte == LF || nextByte == CR) && !reader.hasNextLine()) {
            reader.readLine();
        } else {
            tagNumber = (tagNumber << 1) | (nextByte & 1);
        }
    }

    if (tagNumber == 0 && reader.hasNext()) {
        readTag();
    }

    return (tagNumber & 7) == 0 ? 0 : tagNumber;
}

